# ========== 初始化 vLLM 引擎 ==========
async def init_engine(model_path: str) -> AsyncLLMEngine:
    engine_args = AsyncEngineArgs(
        model=model_path,
        tokenizer=model_path,
        dtype="float16",
        gpu_memory_utilization=0.9,
    )
    engine = await AsyncLLMEngine.from_engine_args(engine_args)
    return engine

# ========== 消费者逻辑 ==========
async def vllm_executor(
    task_queue: asyncio.Queue,
    preloaded_tasks: List[Task],
    engine: AsyncLLMEngine,
    params: SamplingParams,
):
    while True:
        _, _, taskID = await task_queue.get()

        if taskID is None:
            task_queue.task_done()
            break

        task: Task = preloaded_tasks[taskID]

        async for output in engine.generate(
            prompt=task.prompt,
            params=params,
            request_id=str(taskID),
        ):
            if output.finished:
                task.response = output.outputs[0].text
                print(f"[DONE] Task {taskID}: {task.response}")
                break

        task_queue.task_done()

