# ========== 实际调用 ==========
if __name__ == "__main__":
    mp.set_start_method("spawn", force=True)
    import os 

    async def main():
        os.environ["TOKENIZERS_PARALLELISM"] = "false"
        # ✅ 请在这里定义你的 prompt 数据集
        arrival_rate = 10       # 每秒到达的任务数
        retrain_rate = 0.0      # 重训练率
        n_test_samples = 100    # 测试样本数
        strategy = "sync"       # 调度策略
        arrival_pattern = "poisson"     # 到达模式
        model_path = "mistralai/Mistral-7B-Instruct-v0.2"  # 模型路径
        data_path = "data/StanfordNLP"  # 数据集路径
        tokenizer = AutoTokenizer.from_pretrained(model_path, padding_side="left", use_fast=True)
        if tokenizer.pad_token is None:
            tokenizer.pad_token = tokenizer.eos_token
            tokenizer.pad_token_id = tokenizer.eos_token_id
        max_context_length = AutoConfig.from_pretrained(model_path).max_position_embeddings

        # Get producer (loading dataset)
        producer = Producer(
            arrival_rate=arrival_rate, 
            retrain_rate=retrain_rate, 
            n_test_samples=n_test_samples,
            strategy=strategy,
            arrival_pattern=arrival_pattern, 
        )
        preloaded_tasks = producer.load_dataset(
            tokenizer=tokenizer,
            max_length=max_context_length,
            dataset_name=data_path,
        )

        # 启动整个 pipeline
        # results = await run_pipeline(preloaded_tasks, producer, model_path)
        # 初始化任务和队列
        task_queues = [asyncio.Queue(), asyncio.Queue()]

        # Engine & Sampling 参数
        engine = await init_engine(model_path)
        sampling_params = SamplingParams(
            temperature=0.7,
            top_p=0.95,
        )

        # 启动 Producer & Consumer
        await asyncio.gather(
            producer.produce_async(task_queues, preloaded_tasks),
            vllm_executor(task_queues[-1], preloaded_tasks, engine, sampling_params),
        )

        print("\n=== Final Results ===")
        for task in preloaded_tasks:
            print(f"Task {task.taskID}: {task.response.strip()}")

    asyncio.run(main())
